function validate([s, t]) {
  if (typeof s !== 'string' || typeof t !== 'string') return 's and t must be strings.';
  if (s.length > 1000) return 's has at most 1000 letters.';
  if (t.length !== s.length + 1) return 't must be exactly one letter longer than s.';
  if (!/^[a-z]*$/.test(s) || !/^[a-z]*$/.test(t)) return 'Use lowercase English letters only.';
  const counts = new Array(26).fill(0);
  for (const c of t) counts[c.charCodeAt(0) - 97]++;
  for (const c of s) if (--counts[c.charCodeAt(0) - 97] < 0) return 't must contain every letter of s.';
  return null;
}

