function generate(rand, size) {
  const alphabet = size === 'large' || rand() < 0.3 ? 'abcdefghijklmnopqrstuvwxyz' : 'abc';
  const pick = () => alphabet[Math.floor(rand() * alphabet.length)];
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : Math.floor(rand() * 7);
  const s = Array.from({ length: n }, pick);
  const letters = s.slice();
  for (let i = letters.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [letters[i], letters[j]] = [letters[j], letters[i]];
  }
  letters.splice(Math.floor(rand() * (letters.length + 1)), 0, pick());
  return [s.join(''), letters.join('')];
}
